    const value = infomap[e];
    if (!value) {
        java.longToast("请填写密钥");
    }
    return value;
}
var sz = source.getVariable();
var data = [
    ["阅读模式", ""],
    ["多人发音", "&tone_id=51"],
    ["真人发音", "&tone_id=0"],
    ["甜美少女", "&tone_id=1"],
