  if (String(book.intro || "")) return
  let html = java.get("detail")
  // let desc = String(java.getString("$.description", html))
  // if (desc) return desc

  let books = Array.from(
   org.jsoup.Jsoup.parse(html).select(".res-book-item")
  );
  let item = books.find(x => {
    let title = java.getString("h3@text", x)
    return title == book.name
  })

  if (item) return java.getString(".intro@text",item)
})()

