@js:
next = [];
url = result[0];
length = result.length;
p = src.match(/page-link">1\/(\d+)/)||[];
page = Number(p[1]);
if(length < page){
	for(i = 2; i <= page; i++){
		link = String(url).replace(/_\d+/,`_${i}`);
		next.push(link)
		}
		next;
	}else result

@js:
var next=[],
regex=/(pageNum=)(\d+)/,
num=baseUrl.match(regex)[2],
page=JSON.parse(src).totalPage;
if(page>num){
	for(i=1;i<=page;i++){
		url=baseUrl.replace(regex,
			`$1${i}`);
			next.push(url);
		}
	next
	}

