                    return $;
                });
            else
                data = run(1);
            break;


        case '详情':
            if (t2)
                data = file_data(uri);
            else
                data = run(1);
            data.tocUrl = durl(uri + type + "目录" + (data.fid ? type + "本地" : ""));
            break;


        case '目录':
            if (t2)
                data = file_data(uri);
            else {
                data = run(30);

                // 目录下一页
                p = data.total || data.num;
                if (p > 30) {
